// Parse Gemini response and handle errors gracefully
try {
  const response = $json;

  // Check if Gemini returned an error
  if (response.error) {
    console.error('Gemini API error:', response.error);
    throw new Error(response.error.message || 'Gemini API error');
  }

  const geminiResponse = response.candidates?.[0]?.content?.parts?.[0]?.text;

  if (!geminiResponse) {
    throw new Error('No response from Gemini API');
  }

  // Remove markdown code blocks if present
  let cleanJson = geminiResponse
    .replace(/```json\n?/g, '')
    .replace(/```\n?/g, '')
    .trim();

  // Sometimes Gemini adds extra text, try to extract JSON
  const jsonMatch = cleanJson.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    cleanJson = jsonMatch[0];
  }

  let tailoredContent;
  try {
    tailoredContent = JSON.parse(cleanJson);
  } catch (parseError) {
    console.error('Failed to parse Gemini response:', parseError);
    console.error('Response was:', cleanJson);

    // Fallback structure with reasonable defaults
    tailoredContent = {
      matched_skills: ['JavaScript', 'React', 'Node.js'],
      missing_skills: [],
      ats_score: 50,
      tailored_summary: 'Software Development Engineer with Full Stack experience',
      key_achievements: [
        'Developed web applications',
        'Worked with modern tech stack',
        'Team collaboration'
      ],
      recommended_focus: 'Highlight relevant technical skills and experience'
    };
  }

  // Validate the structure
  if (!tailoredContent.matched_skills) tailoredContent.matched_skills = [];
  if (!tailoredContent.missing_skills) tailoredContent.missing_skills = [];
  if (!tailoredContent.ats_score) tailoredContent.ats_score = 0;
  if (!tailoredContent.tailored_summary) tailoredContent.tailored_summary = '';
  if (!tailoredContent.key_achievements) tailoredContent.key_achievements = [];

  return {
    json: {
      ...($json),
      tailoredResume: tailoredContent,
      processed_at: new Date().toISOString(),
      gemini_success: true
    }
  };

} catch (error) {
  console.error('Error in Gemini parsing:', error);

  // Return with fallback data so workflow continues
  return {
    json: {
      ...($json),
      tailoredResume: {
        matched_skills: [],
        missing_skills: [],
        ats_score: 0,
        tailored_summary: 'Error: Could not analyze job match',
        key_achievements: [],
        recommended_focus: 'Manual review required'
      },
      processed_at: new Date().toISOString(),
      gemini_success: false,
      error: error.message
    }
  };
}

// FIX #4: Improved recruiter extraction with strict confidence rules
try {
  const searchResults = $json.organic_results || [];

  if (searchResults.length === 0) {
    return {
      json: {
        ...($json),
        recruiter: {
          recruiter_name: null,
          recruiter_title: null,
          recruiter_email: null,
          linkedin_url: null,
          confidence: 'none',
          source: 'no_results'
        }
      }
    };
  }

  const searchText = searchResults
    .slice(0, 5)
    .map(r => `Title: ${r.title}\nSnippet: ${r.snippet}\nURL: ${r.link}`)
    .join('\n\n---\n\n');

  // Call Gemini to extract recruiter info with strict confidence requirements
  const geminiApiKey = $('Initialize Variables').item.json.geminiApiKey;
  const geminiUrl = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash-exp:generateContent?key=${geminiApiKey}`;

  const response = await $http.post(geminiUrl, {
    contents: [{
      parts: [{
        text: `Extract recruiter information from these LinkedIn search results for ${$json.company}:

${searchText}

CRITICAL RULES:
1. Only return email if you find EXPLICIT evidence (e.g., email in snippet, clear contact pattern)
2. If unsure about email, return NULL - do not guess
3. Mark confidence as 'low' if you're inferring, 'medium' if partial evidence, 'high' only if explicit
4. For email patterns, ONLY generate if you have recruiter's full name AND company domain

Return ONLY valid JSON (no markdown, no code blocks):
{
  "recruiter_name": "Full Name or null",
  "recruiter_title": "Job Title or null",
  "recruiter_email": "email@company.com or null (ONLY if high confidence)",
  "linkedin_url": "LinkedIn profile URL or null",
  "confidence": "high/medium/low"
}

Common email patterns (use ONLY if you have name and are confident):
- firstname.lastname@${$json.company.toLowerCase().replace(/[^a-z0-9]/g, '')}.com
- first.last@${$json.company.toLowerCase().replace(/[^a-z0-9]/g, '')}.com

If no clear recruiter found, return all null values with 'low' confidence.`
      }]
    }],
    generationConfig: {
      temperature: 0.1,  // Lower temperature for more conservative responses
      maxOutputTokens: 512
    }
  });

  const recruiterJson = response.candidates[0].content.parts[0].text
    .replace(/```json\n?/g, '')
    .replace(/```\n?/g, '')
    .trim();

  let recruiterInfo;
  try {
    recruiterInfo = JSON.parse(recruiterJson);

    // FIX #4: Enforce strict confidence rules
    // If confidence is low, force email to null
    if (recruiterInfo.confidence === 'low') {
      recruiterInfo.recruiter_email = null;
    }

    // If no name found, force email to null (can't generate email without name)
    if (!recruiterInfo.recruiter_name || recruiterInfo.recruiter_name === 'null') {
      recruiterInfo.recruiter_email = null;
      recruiterInfo.confidence = 'low';
    }

    recruiterInfo.source = 'gemini_extraction';

  } catch (parseError) {
    console.error('Failed to parse recruiter info:', parseError);
    recruiterInfo = {
      recruiter_name: null,
      recruiter_title: null,
      recruiter_email: null,
      linkedin_url: null,
      confidence: 'low',
      source: 'parse_error'
    };
  }

  return {
    json: {
      ...($json),
      recruiter: recruiterInfo
    }
  };

} catch (error) {
  console.error('Recruiter search failed:', error);
  return {
    json: {
      ...($json),
      recruiter: {
        recruiter_name: null,
        recruiter_title: null,
        recruiter_email: null,
        linkedin_url: null,
        confidence: 'error',
        source: 'api_error',
        error: error.message
      }
    }
  };
}

// Generate daily summary
const allJobs = $input.all();

if (allJobs.length === 0 || allJobs[0].json.message === 'No jobs found today') {
  return [{
    json: {
      date: new Date().toISOString().split('T')[0],
      total_jobs_found: 0,
      jobs_processed: 0,
      avg_ats_score: 0,
      recruiters_found: 0,
      high_match_jobs: 0,
      companies: [],
      status: 'No new jobs today'
    }
  }];
}

const processedJobs = allJobs.filter(j => j.json.tailoredResume);

// Count high-confidence recruiters
const highConfidenceRecruiters = allJobs.filter(j => 
  j.json.recruiter?.recruiter_email && 
  j.json.recruiter.recruiter_email !== 'Not Found' &&
  j.json.recruiter.confidence === 'high'
).length;

const mediumConfidenceRecruiters = allJobs.filter(j => 
  j.json.recruiter?.recruiter_email && 
  j.json.recruiter.recruiter_email !== 'Not Found' &&
  j.json.recruiter.confidence === 'medium'
).length;

const summary = {
  date: new Date().toISOString().split('T')[0],
  total_jobs_found: allJobs.length,
  jobs_processed: processedJobs.length,
  avg_ats_score: Math.round(
    processedJobs.reduce((sum, j) => sum + (j.json.tailoredResume?.ats_score || 0), 0) / 
    (processedJobs.length || 1)
  ),
  recruiters_found: highConfidenceRecruiters + mediumConfidenceRecruiters,
  high_confidence_recruiters: highConfidenceRecruiters,
  medium_confidence_recruiters: mediumConfidenceRecruiters,
  high_match_jobs: processedJobs.filter(j => 
    (j.json.tailoredResume?.ats_score || 0) >= 70
  ).length,
  companies: [...new Set(allJobs.map(j => j.json.company))],
  sources: [...new Set(allJobs.map(j => j.json.source))],
  status: 'Processing complete'
};

console.log('Daily Summary:', JSON.stringify(summary, null, 2));

return [{ json: summary }];
